typeDefs:
type FactCategory =
    | 'biographical'
    | 'preference'
    | 'anecdote'
    | 'opinion'
    | 'plan'
    | 'relationship'
    | 'general';

interface TopicNode {
    id: string;
    chatId: string;
    label: string;
    summary: string;
    keyPoints: string[];
    participants: string[];
    messageRange: { messageIds: string[]; count: number };
    startedAt: string;
    endedAt: string | null;
    sentiment: 'positive' | 'neutral' | 'negative' | 'mixed';
    keywords: string[];
    createdAt: string;
    updatedAt: string;
}

interface CoreFact {
    id: string;
    subject: string;
    content: string;
    category: FactCategory;
    confidence: number;
    createdAt: string;
    expiresAt: string | null;
}

interface PersonIdentity {
    userId: string;
    displayName: string;
    aliases: string[];
    totalMessageCount: number;
    lastSeenAt: string;
    firstSeenAt: string;
}

interface PersonGroupProfile {
    userId: string;
    chatId: string;
    dunbarTier: 1 | 2 | 3 | 4;
    traits: string[];
    interests: string[];
    communicationStyle: string;
    relationToAgent: string;
    messageCount: number;
    lastSeenAt: string;
}

interface RecallOptions {
    chatId?: string;
    userId?: string;
    daysBack?: number;
    maxResults?: number;
    categories?: FactCategory[];
    deepRecallThreshold?: number;
}

interface RecallResult {
    topics: TopicNode[];
    facts: Array<{
        content: string;
        category: FactCategory;
        subject: string;
        confidence: number;
    }>;
    persons: PersonGroupProfile[];
    deepSummary?: string;
}

interface HistoryBrowseRequest {
    /** 自然语言搜索意图 */
    intent: string;
    hints?: {
        chatId?: string;
        userId?: string;
        topicLabel?: string;
        topicId?: string;
        hoursBack?: number;
        daysBack?: number;
    };
    contextWindow?: number;
    maxSegments?: number;
}

interface HistoryBrowseResult {
    answer: string;
    segments: Array<{
        topicLabel: string;
        timeRange: { from: string; to: string };
        messages: Array<{
            messageId: string;
            userId: string;
            displayName: string;
            text: string;
            timestamp: string;
        }>;
        relevanceScore: number;
    }>;
    messagesRead: number;
}

interface MemoryStore {
    /**
     * 统一记忆检索入口
     * 使用向量搜索 + 关键词搜索混合检索
     * @example
     * const result = await memory.recall("alice 东京", {
     *   chatId: "-100xxx",
     *   userId: "alice_123",
     *   categories: ['preference', 'plan'],
     * });
     */
    recall(query: string, options?: RecallOptions): Promise<RecallResult>;

    /**
     * 消息档案检索
     * 话题索引引导 + 模糊搜索 + cheap model 深度阅读
     * @example
     * const result = await memory.browseHistory({
     *   intent: "谁说过要去京都吃抹茶",
     *   hints: { chatId: "-100xxx", daysBack: 7 },
     * });
     */
    browseHistory(request: HistoryBrowseRequest): Promise<HistoryBrowseResult>;

    /**
     * 对指定群组进行反思总结
     * 读取上次反思以来的 topics 和 interactions，生成结构化总结
     */
    reflect(chatId: string): Promise<{
        reflectedPeriod: { from: string; to: string };
        topicsSummary: Array<{ label: string; summary: string; participants: string[]; sentiment: string }>;
        personUpdates: Array<{ userId: string; chatId: string; changes: string }>;
        groupUpdates: string;
        newCoreFacts: string[];
        mergedEpisodes: number;
        insights: string;
    }>;
}

